"use strict";

const PLUGIN_ID = 'holdingtank-status';

module.exports = function (app) {
  const plugin = {
    id: PLUGIN_ID,
    name: 'Holding Tank Status',
    description:
      'Holds holdingTank.* status values written by the holding tank discharge daemon',
    schema: {},

    start: function () {
      const paths = [
        'holdingTank.dumpTimeRemaining',
        'holdingTank.dumpTimeRemainingText',
        'holdingTank.dumpAutoActive',
        'holdingTank.lastAutoDump'
      ];

      paths.forEach((p) => {
        app.registerPutHandler('vessels.self', p, (context, path, value, cb) => {
          app.handleMessage(PLUGIN_ID, {
            updates: [
              {
                $source: PLUGIN_ID,
                values: [{ path, value }]
              }
            ]
          });
          cb({ state: 'COMPLETED', statusCode: 200 });
          return { state: 'PENDING' };
        });
      });

      app.setPluginStatus('Holding tank status paths registered');
    },

    stop: function () {}
  };

  return plugin;
};
